<?php
namespace EyeDonation\SiteMigrations;
defined('ABSPATH') || exit;
function registry(){return [
 '001_create_approved_navigation'=>['description'=>'Create approved primary and footer menus','dependencies'=>[]],
 '002_bind_shared_navigation'=>['description'=>'Bind only marked header/footer navigation','dependencies'=>['001_create_approved_navigation']],
 '003_apply_homepage_content'=>['description'=>'Replace approved homepage content, preserving its ID','dependencies'=>[]],
 '004_apply_approved_page_settings'=>['description'=>'Apply approved front-page and logo settings','dependencies'=>['003_apply_homepage_content']],
 '005_configure_search'=>['description'=>'Apply approved public search settings','dependencies'=>[]],
 '006_verify_and_rebuild_search'=>['description'=>'Rebuild current destination public search text','dependencies'=>['005_configure_search']]
];}
function checksum($id){$files=array_merge(glob(DIR.'/src/*.php'),glob(DIR.'/payloads/*'));sort($files);$hash=hash_init('sha256');hash_update($hash,$id);foreach($files as $file)hash_update($hash,basename($file).file_get_contents($file));return hash_final($hash);}
function history(){return get_option('edm_history',[]);}
function save_history($history){update_option('edm_history',$history,false);}
function preflight(){if(is_multisite())fail('Version 1 supports single-site WordPress only.');if(get_stylesheet()!=='eyedonation')fail('Activate the matching EyeDonation theme before processing.');if(wp_get_theme()->get('Version')!==VERSION)fail('Theme and migration releases must match 0.1.0.');if(version_compare(get_bloginfo('version'),'6.6','<'))fail('WordPress 6.6 or later required.');if(!current_user_can('manage_options')||!current_user_can('edit_theme_options')||!current_user_can('edit_pages'))fail('Administrator and target editing capabilities required.');}
function preview(){preflight();$h=history();$rows=[];foreach(registry() as $id=>$migration){try{if(isset($h[$id]['checksum'])&&$h[$id]['checksum']!==checksum($id))fail('Packaged checksum differs from recorded migration. Use a new migration.');$ops=plan($id);$rows[$id]=['status'=>($h[$id]['status']??'pending')==='completed'?'completed':'ready','operations'=>$ops,'fingerprint'=>fingerprint($ops),'checksum'=>checksum($id)];}catch(\Throwable $error){$rows[$id]=['status'=>'blocked','reason'=>$error->getMessage(),'checksum'=>checksum($id)];}}$result=['created'=>time(),'actor'=>get_current_user_id(),'rows'=>$rows,'assets'=>resolve_assets(),'theme'=>get_stylesheet(),'version'=>VERSION];update_option('edm_preview',$result,false);return $result;}
function lock_acquire(){global $wpdb;$token=wp_generate_uuid4();$lease=['token'=>$token,'expires'=>time()+90];if(add_option('edm_run_lock',$lease,'',false))return $token;$old=get_option('edm_run_lock');if(($old['expires']??PHP_INT_MAX)>=time())fail('Another migration request owns the current lease.');$deleted=$wpdb->query($wpdb->prepare("DELETE FROM $wpdb->options WHERE option_name=%s AND option_value=%s",'edm_run_lock',maybe_serialize($old)));wp_cache_delete('edm_run_lock','options');if(!$deleted||!add_option('edm_run_lock',$lease,'',false))fail('Lease acquisition lost to another request.');return $token;}
function lock_check($token){$lease=get_option('edm_run_lock');if(($lease['token']??'')!==$token||($lease['expires']??0)<=time())fail('Worker lease expired or changed; retry from a fresh preview.');}
function lock_release($token){global $wpdb;$lease=get_option('edm_run_lock');if(($lease['token']??'')===$token){$wpdb->query($wpdb->prepare("DELETE FROM $wpdb->options WHERE option_name=%s AND option_value=%s",'edm_run_lock',maybe_serialize($lease)));wp_cache_delete('edm_run_lock','options');}}
function batch($id){preflight();$registry=registry();if(!isset($registry[$id]))fail('Unregistered migration ID.');$token=lock_acquire();try{$h=history();$old=$h[$id]??[];if(isset($old['checksum'])&&$old['checksum']!==checksum($id))fail('Recorded checksum changed.');if(($old['status']??'')==='completed')return ['status'=>'completed','message'=>'Completed migration skipped; use a new migration to repair drift.'];foreach($registry[$id]['dependencies'] as $dep)if(($h[$dep]['status']??'')!=='completed')fail('Dependency incomplete: '.$dep);
 $preview=get_option('edm_preview');$row=$preview['rows'][$id]??null;if(!$row||$row['status']!=='ready'||$row['checksum']!==checksum($id)||($preview['actor']??0)!==get_current_user_id())fail('Successful current-user preview required.');
 $ops=plan($id);$checkpoints=$old['operations']??[];
 // Compare only unprocessed operations; creation reconciles from stable ownership.
 foreach($ops as $op){if(isset($checkpoints[$op['key']])){if($op['kind']!=='rebuild'&&$op['action']!=='already-satisfied')fail('Completed operation drift: '.$op['key']);continue;}$expected=null;foreach($row['operations'] as $candidate)if($candidate['key']===$op['key'])$expected=$candidate;if(!$expected)fail('Plan changed; preview again.');if(fingerprint($expected)!==fingerprint($op)){if(!($expected['action']==='create'&&$op['action']==='already-satisfied'&&$op['after']===$expected['after']))fail('Destination state changed after preview.');}}
 $h[$id]=array_merge($old,['status'=>'running','checksum'=>checksum($id),'actor'=>get_current_user_id(),'run_id'=>$old['run_id']??wp_generate_uuid4(),'started'=>$old['started']??time(),'heartbeat'=>time(),'operations'=>$checkpoints]);save_history($h);
 foreach($ops as $op){if(isset($h[$id]['operations'][$op['key']]))continue;lock_check($token);$result=apply_operation($op);lock_check($token);$h[$id]['operations'][$op['key']]=['status'=>'completed','timestamp'=>time(),'destination_id'=>$result,'before'=>$op['before'],'after_fingerprint'=>fingerprint($op['after'])];$h[$id]['heartbeat']=time();save_history($h);return ['status'=>'running','message'=>'Verified '.$op['key']];}
 if($id==='006_verify_and_rebuild_search'){lock_check($token);if(get_option('eds_rebuild_job')){\EyeDonation\Search\rebuild_batch();return ['status'=>'running','message'=>'Processing destination search index batch'];}if(!get_option('eds_rebuild_completed'))fail('Search rebuild completion missing.');}
 foreach(plan($id) as $op)if($op['kind']!=='rebuild'&&$op['action']!=='already-satisfied')fail('Final postcondition failed: '.$op['key']);$h[$id]['status']='completed';$h[$id]['completed']=time();save_history($h);return ['status'=>'completed','message'=>'All postconditions verified.'];
 }catch(\Throwable $error){$h=history();$h[$id]=array_merge($h[$id]??[],['status'=>'failed','checksum'=>checksum($id),'error'=>$error->getMessage(),'heartbeat'=>time()]);save_history($h);throw $error;}finally{lock_release($token);}}
